# Let's create candidate trigger patterns and test them
# Trigger: 3-5 pixel square, 1 pixel from corner
# Types: white square, checkerboard, random noise

def create_trigger_image(trigger_type='white', size=4, corner='top_left'):
    """Create a 32x32 image with just the trigger pattern"""
    img = np.zeros((3, 32, 32), dtype=np.float32)

    # Position: 1 pixel from corner
    if corner == 'top_left':
        r, c = 1, 1
    elif corner == 'top_right':
        r, c = 1, 32 - size - 1
    elif corner == 'bottom_left':
        r, c = 32 - size - 1, 1
    elif corner == 'bottom_right':
        r, c = 32 - size - 1, 32 - size - 1

    if trigger_type == 'white':
        pattern = np.ones((size, size), dtype=np.float32)
    elif trigger_type == 'checkerboard':
        pattern = np.zeros((size, size), dtype=np.float32)
        for i in range(size):
            for j in range(size):
                pattern[i, j] = 1.0 if (i + j) % 2 == 0 else 0.0
    elif trigger_type == 'noise':
        pattern = np.random.rand(size, size).astype(np.float32)

    for ch in range(3):
        img[ch, r:r+size, c:c+size] = pattern

    return img

def add_trigger_to_batch(x_batch, trigger_type='white', size=4, corner='top_left'):
    """Add trigger to a batch of images (uint8 0-255)"""
    x_triggered = x_batch.copy()
    trigger = create_trigger_image(trigger_type, size, corner)
    # Convert trigger to uint8 (0-255)
    trigger_uint8 = (trigger * 255).astype(np.uint8)
    for i in range(len(x_batch)):
        x_triggered[i] = np.maximum(x_triggered[i], trigger_uint8)
    return x_triggered

